            "Microsoft明确预告下期将扩大工具覆盖，几乎各国估计都可能上修，中国预计上修更大；当前中国数值存在覆盖局限。",
            "分档仅为本站对这一指标的展示阈值，不是Microsoft官方分级，更不是综合AI能力排名。",
            "规模换算混用2026扩散率和2025人口，仅作量级参考，不是MAU、月活跃付费用户或厂商官方用户总数。"
